let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const headers = { "content-type": "application/json" };
const accountsOf = (from, to) => [from, to];

function respond(status, body, { accounts, committed, messages = [], ordering = [], failures = [], retryable = false }) {
  console.log(JSON.stringify({
    http: { status, headers, body },
    database: { accounts, transaction: { committed } },
    messages,
    ordering,
    failures,
    retryability: retryable
  }));
}

const unchanged = accountsOf(
  { id: input.fromId, balance: input.fromBalance, version: input.fromVersion },
  { id: input.toId, balance: input.toBalance, version: input.toVersion }
);

const replay = input.existingTransfer ?? input.replay ?? input.previousResult;
const seen = Array.isArray(input.seenKeys) ? input.seenKeys.includes(input.idempotencyKey) : input.replayed === true;

if (replay || seen) {
  const prior = replay && typeof replay === "object" ? replay : {};
  respond(200, {
    transferId: prior.transferId ?? input.transferId,
    fromBalance: prior.fromBalance ?? input.fromBalance,
    toBalance: prior.toBalance ?? input.toBalance,
    replayed: true
  }, { accounts: unchanged, committed: false });
} else if (
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== input.fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== input.toVersion) ||
  input.versionConflict === true
) {
  respond(409, { error: "version_conflict", transferId: input.transferId }, {
    accounts: unchanged, committed: false, failures: ["version_conflict"], retryable: true
  });
} else if (!Number.isFinite(input.amount) || input.amount <= 0) {
  respond(400, { error: "invalid_amount", transferId: input.transferId }, {
    accounts: unchanged, committed: false, failures: ["invalid_amount"]
  });
} else if (input.fromBalance < input.amount) {
  respond(422, { error: "insufficient_funds", transferId: input.transferId }, {
    accounts: unchanged, committed: false, failures: ["insufficient_funds"]
  });
} else {
  const fromBalance = input.fromBalance - input.amount;
  const toBalance = input.toBalance + input.amount;
  const fromVersion = input.fromVersion + 1;
  const toVersion = input.toVersion + 1;
  respond(201, { transferId: input.transferId, fromBalance, toBalance, fromVersion, toVersion }, {
    accounts: accountsOf(
      { id: input.fromId, balance: fromBalance, version: fromVersion },
      { id: input.toId, balance: toBalance, version: toVersion }
    ),
    committed: true,
    messages: [{ type: "transfer.completed", transferId: input.transferId, fromId: input.fromId, toId: input.toId, amount: input.amount }],
    ordering: ["debit", "credit", "event"]
  });
}

